DO $$ BEGIN IF EXISTS(SELECT 1 FROM auth.users WHERE id::text LIKE 'd6250001-%') OR EXISTS(SELECT 1 FROM public.profiles WHERE user_id::text LIKE 'd6250001-%') OR EXISTS(SELECT 1 FROM public.listings WHERE id::text LIKE 'd6250002-%') OR EXISTS(SELECT 1 FROM public.viewings WHERE listing_id::text LIKE 'd6250002-%') OR EXISTS(SELECT 1 FROM public.leads WHERE listing_id::text LIKE 'd6250002-%') OR EXISTS(SELECT 1 FROM public.notifications WHERE user_id::text LIKE 'd6250001-%') OR EXISTS(SELECT 1 FROM public.organizations WHERE id::text LIKE 'd6250004-%') OR EXISTS(SELECT 1 FROM public.organization_memberships WHERE user_id::text LIKE 'd6250001-%') THEN RAISE EXCEPTION 'Synthetic residue'; END IF; IF EXISTS(SELECT 1 FROM pg_class WHERE relnamespace=pg_my_temp_schema()) OR EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace=pg_my_temp_schema()) THEN RAISE EXCEPTION 'Temporary residue'; END IF; END $$; SELECT 'zero synthetic and temporary residue' AS cleanup;